-- UK bank holidays: create table (postgres)
-- Generated by uk_bank_holidays. Safe to re-run: an existing table (and its data) is left untouched.

CREATE TABLE IF NOT EXISTS "bank_holidays" (
    "holiday_date" date NOT NULL,
    "rule_id" varchar(100) NOT NULL,
    "holiday_key" varchar(100) NOT NULL,
    "holiday_name" varchar(200) NOT NULL,
    "holiday_type" varchar(20) NOT NULL,
    "england_and_wales" boolean NOT NULL,
    "scotland" boolean NOT NULL,
    "northern_ireland" boolean NOT NULL,
    "is_substitute" boolean NOT NULL,
    "notes" varchar(500) NULL,
    "source_ids" varchar(500) NULL,
    PRIMARY KEY ("holiday_date", "rule_id")
);
